{
  "name": "@juspay/rescript-blend",
  "version": "0.0.38",
  "description": "ReScript bindings for @juspay/blend-design-system",
  "scripts": {
    "build": "rescript",
    "clean": "rescript clean",
    "watch": "rescript build -w",
    "format": "rescript format",
    "format:check": "rescript format -c",
    "generate": "node scripts/generate.mjs",
    "generate:raw": "rescript-bindgen --pkg @juspay/blend-design-system --node-modules ./node_modules --no-install --out src --project . --webapi --report --json-summary src/_bindgen-summary.json --clean --yes"
  },
  "files": [
    "src/**/*.res",
    "src/**/*.resi",
    "rescript.json",
    "README.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20"
  },
  "keywords": [
    "rescript",
    "juspay",
    "blend-design-system",
    "react"
  ],
  "author": "Juspay Technologies",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/juspay/blend-rescript.git"
  },
  "bugs": {
    "url": "https://github.com/juspay/blend-rescript/issues"
  },
  "homepage": "https://github.com/juspay/blend-rescript#readme",
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "dependencies": {
    "@juspay/blend-design-system": "0.0.38"
  },
  "peerDependencies": {
    "@rescript/react": ">=0.12.0",
    "react": ">=18.0.0",
    "react-dom": ">=18.0.0",
    "rescript": ">=12.0.0",
    "rescript-webapi": ">=0.10.0"
  },
  "devDependencies": {
    "@juspay/rescript-bindgen": "1.4.0-beta.5",
    "@rescript/react": "^0.15.0",
    "rescript": "^12.2.0",
    "rescript-webapi": "^0.10.0"
  }
}

type props = {
  tokens: HighchartsSharedSharedTypes.multiSelectV2TokensType,
  primaryAction?: HighchartsSharedSharedTypes.multiSelectV2PrimaryActionConfig,
  secondaryAction?: HighchartsSharedSharedTypes.multiSelectV2SecondaryActionConfig,
  selected: array<string>,
  onClose: unit => unit,
}

@module("@juspay/blend-design-system")
external make: React.component<props> = "MultiSelectV2MenuActions"

type props = {
  actions?: ButtonV2Types.CardV2Actions.t, // ⓘ was `ButtonV2Props | ButtonV2Props[]` — opaque; build with CardV2Actions.fromButtonV2Props / CardV2Actions.fromButtonV2Propss
  centered?: bool,
}

@module("@juspay/blend-design-system")
external make: React.component<props> = "CardV2Actions"

type props = {
  inputRef: React.ref<Nullable.t<Dom.element>>,
  value: string,
  onChange: ReactEvent.Form.t => unit,
  placeholder?: string,
  ariaLabel?: string,
  onArrowKeyToFirstOption?: unit => unit,
}

@module("@juspay/blend-design-system")
external make: React.component<props> = "MultiSelectV2MenuSearch"

type props = {
  ...ProgressBarV2Types.progressBarV2InternalProps,
  size: ProgressBarV2Types.progressBarV2Size,
  appearance: ProgressBarV2Types.progressBarV2Appearance,
}

@module("@juspay/blend-design-system")
external make: React.component<props> = "CircularProgressBarV2"
